import { HomeMain } from '../../slots/defs/homeMain';
import { Templates } from './Templates';

export const contribution = HomeMain.fill({ order: 9.8, Component: Templates });
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { sheetKey, useCurrentSheet } from '../session/session';

/** A claim template: its name, the amount (two decimals) and note a claim made from it gets. */
export type ClaimTemplate = { name: string; amount: string; note: string };

/** The query key for the sheet's claim templates; under sheetKey, so re-loading the sheet re-reads them. */
export const templatesKey = (sheet: string) => [...sheetKey(sheet), 'templates'] as const;

/** The sheet's claim templates, by name. */
export function useTemplates() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: templatesKey(sheet),
    queryFn: () => getJson<ClaimTemplate[]>(`/api/sheets/${encodeURIComponent(sheet)}/templates`),
    enabled: !!sheet,
  });
}
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { AMOUNT } from '../claims/claims';
import { templatesKey, useTemplates } from './templates';
import type { ClaimTemplate } from './templates';
import { useOneAtATime } from '../../query/useOneAtATime';

const EMPTY = { name: '', amount: '', note: '' };

// The sheet's claim templates and the form that saves one; a blank name or an amount the claim form would refuse is
// refused, and saving a name again replaces its template.
export function Templates() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const templates = useTemplates().data ?? [];
  const [form, setForm] = useState(EMPTY);
  const [error, setError] = useState('');
  const queryClient = useQueryClient();
  const once = useOneAtATime();

  const save = useMutation({
    mutationFn: (input: typeof EMPTY) =>
      postJson<ClaimTemplate[]>(`/api/sheets/${encodeURIComponent(sheet)}/templates?user=${encodeURIComponent(user)}`, input),
    onSuccess: async (saved) => {
      setForm(EMPTY);
      setError('');
      queryClient.setQueryData(templatesKey(sheet), saved);
      await queryClient.invalidateQueries({ queryKey: templatesKey(sheet) });
    },
    onError: () => setError('That template was refused: it needs a name and an amount the claim form accepts.'),
  });

  if (!user || !sheet) return null;

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    if (!form.name.trim()) {
      setError('Type the template name.');
      return;
    }
    if (!AMOUNT.test(form.amount.trim())) {
      setError('Type an amount with at most two decimals.');
      return;
    }
    once(() => save.mutateAsync(form));
  };

  const change = (patch: Partial<typeof EMPTY>) => {
    setForm((f) => ({ ...f, ...patch }));
    setError('');
  };

  return (
    <section data-testid="templates">
      <ul data-testid="template-list">
        {templates.map((t) => (
          <li key={t.name} data-testid={`template-row-${t.name}`}>
            <span data-testid="template-name">{t.name}</span> <span data-testid="template-amount">{t.amount}</span>{' '}
            <span data-testid="template-note" style={{ whiteSpace: 'pre' }}>
              {t.note}
            </span>
          </li>
        ))}
      </ul>
      <form onSubmit={submit} data-testid="template-form">
        <input data-testid="template-form-name" placeholder="Template name" value={form.name} onChange={(e) => change({ name: e.target.value })} />
        <input data-testid="template-form-amount" placeholder="Amount" value={form.amount} onChange={(e) => change({ amount: e.target.value })} />
        <input data-testid="template-form-note" placeholder="Note" value={form.note} onChange={(e) => change({ note: e.target.value })} />
        <button type="submit" data-testid="template-form-submit" disabled={save.isPending}>
          Save template
        </button>
        {error && <span data-testid="template-form-error">{error}</span>}
      </form>
    </section>
  );
}
import type { ComponentType } from 'react';

// The contribution store. It imports NOTHING — that is deliberate: discovery (slots/discover.ts)
// pulls in every feature's contribution file, and those files reach a slot definition, which
// reaches defineSlot, which reaches this file. Keeping the arrows one-way (discover -> features ->
// defs -> Slot -> registry) is what stops the module graph forming a cycle.

export type Registered = {
  slot: string;
  order: number;
  /** Source file — the React key and the deterministic tie-break for equal `order`. */
  from: string;
  Component: ComponentType<never>;
};

const contributions: Registered[] = [];

/** Called once per contribution at startup, by slots/discover.ts. */
export function register(entry: Registered): void {
  contributions.push(entry);
}

export function forSlot(id: string): Registered[] {
  return contributions
    .filter((c) => c.slot === id)
    .sort((a, b) => a.order - b.order || a.from.localeCompare(b.from));
}
import { register } from './registry';
import type { Registered } from './registry';

// Discovery: every `features/**/*.slot.tsx` in the app is found here and registered, so there is
// no explicit list of features. A file exports `contribution`, or `contributions` for more than
// one. Imported once for its side effect by main.tsx.
